\begin{tikzpicture}[x=1cm,y=1cm,line width=0.8pt,every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-1.2,-3.9) rectangle (7.0,4.9);
\coordinate (O) at (0,0);\coordinate (R) at (1.8,2);\coordinate (B) at (1.8,-2);
\coordinate (RR) at (3.9,3);\coordinate (RB) at (3.9,1);\coordinate (BR) at (3.9,-1);\coordinate (BB) at (3.9,-3);
\node[left] at (O) {Start};
\node at (1.8,4.4) {1st draw};\node at (3.9,4.4) {2nd draw};\node at (6,4.4) {3rd draw};
\draw (O)--(R) node[midway,above left] {$\frac{4}{7}$};
\draw (O)--(B) node[midway,below left] {$\frac{3}{7}$};
\draw (R)--(RR) node[midway,above] {$\frac{3}{6}$};
\draw (R)--(RB) node[midway,below] {$\frac{3}{6}$};
\draw (B)--(BR) node[midway,above] {$\frac{4}{6}$};
\draw (B)--(BB) node[midway,below] {$\frac{2}{6}$};
\draw (RR)--(6,3.5);\draw (RR)--(6,2.5);\draw (RB)--(6,1.5);\draw (RB)--(6,0.5);
\draw (BR)--(6,-0.5);\draw (BR)--(6,-1.5);\draw (BB)--(6,-2.5);\draw (BB)--(6,-3.5);
\node[fill=white,inner sep=2pt] at (R) {R};\node[fill=white,inner sep=2pt] at (B) {B};
\node[fill=white,inner sep=2pt] at (RR) {R};\node[fill=white,inner sep=2pt] at (RB) {B};
\node[fill=white,inner sep=2pt] at (BR) {R};\node[fill=white,inner sep=2pt] at (BB) {B};
\node[right] at (6,3.5) {R};\node[right] at (6,2.5) {B};\node[right] at (6,1.5) {R};\node[right] at (6,0.5) {B};
\node[right] at (6,-0.5) {R};\node[right] at (6,-1.5) {B};\node[right] at (6,-2.5) {R};\node[right] at (6,-3.5) {B};
\end{tikzpicture}

